<script setup lang="ts">
import {ref,onMounted,watch,computed} from 'vue';import {ElMessage} from 'element-plus';import {useAuthApi,isStaleAuthError,dateTime,roleName} from '../api';
const api=useAuthApi();
const props=defineProps<{refreshKey:number;initialId?:string}>();const emit=defineEmits(['changed']);const items=ref<any[]>([]);const selected=ref<any>(null);const tab=ref('summary');const feedback=ref('');const note=ref('');const busy=ref(false);const onlyPending=ref(true);
const filtered=computed(()=>onlyPending.value?items.value.filter(r=>r.review_status!=='reviewed'):items.value);
let refreshRequest=0;
async function refresh(){const request=++refreshRequest;try{const result=await api('/clinician/reviews');if(request===refreshRequest)items.value=result.items;}catch(e){if(request===refreshRequest&&!isStaleAuthError(e))ElMessage.error((e as Error).message);}}
let selectionRequest=0;
async function open(id:string){const request=++selectionRequest;try{const result=await api('/clinician/followups/'+id);if(request!==selectionRequest)return;selected.value=result;feedback.value=result.feedback||'';note.value=result.clinician_summary?.note||'';tab.value='summary';}catch(e){if(request===selectionRequest&&!isStaleAuthError(e))ElMessage.error((e as Error).message);}}
async function save(published:boolean){busy.value=true;try{await api(`/clinician/followups/${selected.value.id}/review`,'POST',{expectedVersion:selected.value.version,feedback:feedback.value,published,summary:{note:note.value}});ElMessage.success(published?'审核与反馈已发布':'审核已保存，反馈尚未发布');await open(selected.value.id);await refresh();emit('changed');}catch(e){if(!isStaleAuthError(e))ElMessage.error((e as Error).message);}finally{busy.value=false;}}
onMounted(async()=>{await refresh();if(props.initialId)await open(props.initialId);});watch(()=>props.refreshKey,refresh);watch(()=>props.initialId,id=>{if(id)void open(id);});
</script>
<template><section class="page-heading"><div><span class="eyebrow">FOLLOW-UP REVIEW</span><h1>随访审核</h1><p>核对患者原话与采集摘要，再向患者发布您的反馈。</p></div><el-switch v-model="onlyPending" active-text="只看待审核"/></section><section class="panel"><el-table :data="filtered" empty-text="当前没有需要审核的记录"><el-table-column label="患者" prop="name" min-width="120"/><el-table-column label="提交时间" min-width="160"><template #default="{row}">{{dateTime(row.submitted_at||row.started_at)}}</template></el-table-column><el-table-column label="采集情况" min-width="180"><template #default="{row}"><span class="status" :class="row.priority==='urgent'?'red':row.patient_confirmed?'green':'orange'">{{row.priority==='urgent'?'优先人工处理':row.patient_confirmed?'患者已确认':'需协助核对'}}</span></template></el-table-column><el-table-column label="审核状态" width="115"><template #default="{row}">{{row.review_status==='reviewed'?'已审核':'待审核'}}</template></el-table-column><el-table-column width="140"><template #default="{row}"><el-button text type="primary" @click="open(row.id)">查看并审核</el-button></template></el-table-column></el-table></section>
<section class="panel review-detail" v-if="selected"><div class="panel-toolbar"><div><h2>随访记录</h2><p class="muted">{{dateTime(selected.started_at)}} · {{selected.patient_confirmed?'患者已确认采集内容':'患者未确认，或请求医生协助核对'}}</p></div><span class="status" :class="selected.feedback_published?'green':'gray'">{{selected.feedback_published?'反馈已发布':'反馈未发布'}}</span></div><section v-if="selected.briefSummary" class="shared-brief" aria-labelledby="shared-brief-title"><div class="shared-brief-heading"><h3 id="shared-brief-title">{{selected.briefSummary.title}}</h3><span class="status gray">与患者端一致</span></div><p class="muted">根据患者本次回答整理。{{selected.review_status==='reviewed'?'医生审核与发布反馈见右侧。':'待医生核对，请结合下方原话与证据审核。'}}</p><dl class="brief-items"><template v-for="(item,index) in selected.briefSummary.items" :key="index"><dt>{{item.label}}</dt><dd>{{item.value}}</dd></template></dl><p class="brief-note">{{selected.briefSummary.note}}</p></section><div class="review-columns"><div class="review-source"><el-tabs v-model="tab"><el-tab-pane label="采集摘要" name="summary"><div v-if="selected.priority==='urgent'" class="urgent-notice">这份记录被标为优先人工处理，请核对原始描述。</div><div v-for="item in selected.summary?.items||[]" :key="item.field" class="summary-item"><div><strong>{{item.label}}</strong><span class="status gray" v-if="item.status!=='reported'">{{item.status==='unknown'?'不确定':item.status==='declined'?'未回答':'未采集'}}</span></div><p>{{item.value}}</p></div><div class="notice-card"><strong>后台辅助复核</strong><p v-if="!selected.ai_review" class="muted">{{selected.jobs?.[0]?.status==='failed'?'复核暂未完成，请以患者原话为准。':'复核尚未完成，您可以先核对原话。'}}</p><template v-else><p class="muted">结果仅用于辅助核对，不会自动发布给患者。</p><div v-for="run in selected.ai_review.runs" :key="run.role"><strong>{{roleName(run.role)}}</strong><p v-for="issue in run.output.issues||[]" :key="issue.turnId">{{issue.description}}</p><p v-for="line in run.output.notes||[]" :key="line">{{line}}</p><p v-if="run.output.note">{{run.output.note}}</p></div></template></div></el-tab-pane><el-tab-pane label="对话原文" name="transcript"><div class="transcript-entry assistant">您好，我是随访助手，我们先聊聊您最近的身体情况。</div><template v-for="turn in selected.turns" :key="turn.id"><div class="transcript-entry patient"><small>{{turn.source==='correction'?'患者更正':'患者'}}</small><p>{{turn.patient_text}}</p></div><div class="transcript-entry assistant" v-if="turn.assistant_text"><small>随访助手</small><p>{{turn.assistant_text}}</p></div></template></el-tab-pane><el-tab-pane label="Agent 处理记录" name="agents"><p class="muted">以下为结构化工作记录、引用与耗时，保留处理过程供您核对。</p><el-collapse><el-collapse-item v-for="(run,index) in selected.agentRuns" :key="index" :title="`${roleName(run.role)} · ${run.provider} · ${run.elapsed_ms}ms`" :name="index"><pre class="trace-json">{{JSON.stringify(run.output,null,2)}}</pre></el-collapse-item></el-collapse></el-tab-pane></el-tabs></div><div class="review-form"><h3>医生审核</h3><el-form label-position="top"><el-form-item label="审核备注" for="review-note"><el-input id="review-note" v-model="note" type="textarea" :rows="4" placeholder="填写核对结果及需跟进的事项，仅医生端可见" maxlength="5000"/></el-form-item><el-form-item label="患者可见反馈" for="review-feedback"><el-input id="review-feedback" v-model="feedback" type="textarea" :rows="5" placeholder="填写准备发送给患者的反馈" maxlength="6000"/></el-form-item></el-form><p class="muted">保存审核不会向患者发布反馈。点击下方“审核并发布反馈”后，患者才会看到文字内容。</p><div class="review-buttons"><el-button @click="save(false)" :loading="busy">保存审核</el-button><el-button type="primary" @click="save(true)" :loading="busy">审核并发布反馈</el-button></div></div></div></section>
</template>

<style scoped>
.shared-brief{margin:0 24px 24px;padding:20px 22px;background:#edf5f2;border:1px solid #d5e6df;border-radius:10px}.shared-brief-heading{display:flex;align-items:center;gap:14px;flex-wrap:wrap}.shared-brief-heading h3{font-size:16px;margin:0}.shared-brief>p{font-size:12px;margin:12px 0}.brief-items{display:grid;grid-template-columns:100px minmax(0,1fr);gap:10px 18px;font-size:13px;line-height:1.8}.brief-items dt{color:#6d8277}.brief-items dd{margin:0;white-space:pre-wrap;overflow-wrap:anywhere}.shared-brief .brief-note{border-top:1px solid #d5e6df;padding-top:12px;color:#637b6e;margin-bottom:0}@media(max-width:760px){.shared-brief{margin:0 16px 20px;padding:16px}.brief-items{grid-template-columns:75px minmax(0,1fr);gap:10px;font-size:12px}}
</style>
